/**
 * Builds supabase/seed.sql from the demo catalogue in src/data/catalog.ts.
 * Run: npx tsx scripts/generate-seed.ts
 * The seed is idempotent: it skips products whose slug already exists.
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { categories, products } from "../src/data/catalog";

const q = (v: string | null | undefined) =>
  v == null ? "null" : `'${String(v).replaceAll("'", "''")}'`;

const lines: string[] = [
  "-- DUKES starting catalogue (generated by scripts/generate-seed.ts).",
  "-- Products marked 'demo' in their tags are sample data: edit or archive them in /admin.",
  "begin;",
];

categories.forEach((c, i) => {
  lines.push(
    `insert into public.categories (id, slug, name, description, image, sort) values (${q(c.id)}, ${q(c.slug)}, ${q(c.name)}, ${q(c.description)}, ${q(c.image)}, ${i}) on conflict (id) do nothing;`,
  );
  c.subcategories.forEach((s, j) =>
    lines.push(
      `insert into public.subcategories (category_id, slug, name, sort) values (${q(c.id)}, ${q(s.slug)}, ${q(s.name)}, ${j}) on conflict (category_id, slug) do nothing;`,
    ),
  );
});

for (const p of products) {
  lines.push(`
with ins as (
  insert into public.products (slug, name, style, description, category_id, subcategory, leather, construction, lining, sole, care, featured, is_new, status, created_at)
  values (${q(p.slug)}, ${q(p.name)}, ${q(p.style)}, ${q(p.description)}, ${q(p.categoryId)}, ${q(p.subcategory)}, ${q(p.leather)}, ${q(p.construction)}, ${q(p.lining)}, ${q(p.sole === "Not applicable" ? "" : p.sole)}, ${q(p.care)}, ${p.featured}, ${p.isNew}, 'active', ${q(p.createdAt)})
  on conflict (slug) do nothing
  returning id
), imgs as (
  insert into public.product_images (product_id, color, url, alt, sort)
  select ins.id, x.color, x.url, x.alt, x.sort from ins, (values
    ${Object.entries(p.images)
      .flatMap(([color, imgs]) =>
        imgs.map((img, k) => `(${q(color)}, ${q(img.src)}, ${q(img.alt)}, ${k})`),
      )
      .join(",\n    ")}
  ) as x(color, url, alt, sort)
  returning 1
)
insert into public.variants (product_id, sku, size, size_system, color_name, color_hex, stock, price)
select ins.id, x.sku, x.size, x.size_system, x.color_name, x.color_hex, x.stock, x.price from ins, (values
    ${p.variants
      .map(
        (v) =>
          `(${q(v.sku)}, ${q(v.size)}, ${q(v.sizeSystem)}, ${q(v.color.name)}, ${q(v.color.hex)}, ${v.stock}, ${v.price})`,
      )
      .join(",\n    ")}
) as x(sku, size, size_system, color_name, color_hex, stock, price);`);
}

lines.push("commit;");
const out = join(__dirname, "..", "supabase", "seed.sql");
writeFileSync(out, lines.join("\n") + "\n");
console.log(`Wrote ${out}: ${categories.length} categories, ${products.length} products.`);
